<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\AuditService;
use App\Support\LegacyResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Throwable;
class ShiftLogController extends Controller
{
 public function __construct(private AuditService $audit){}
 private function user(Request $r){return $r->attributes->get('jwt_user');}
 public function stopReasons(){return response()->json(['success'=>true,'data'=>DB::table('stop_reasons')->select('id','code','description','category')->where('active',true)->orderBy('category')->orderBy('description')->get()->all()]);}
 public function index(Request $r){$q=DB::table('shift_logs as sl')->join('equipment as e','sl.equipment_id','=','e.id')->join('users as u','sl.operator_id','=','u.id')->leftJoin('stop_reasons as sr','sl.stop_reason_id','=','sr.id')->select('sl.*','e.name as equipment_name','e.code as equipment_code','u.full_name as operator_name','sr.description as stop_reason');if($r->filled('date'))$q->where('sl.shift_date',$r->input('date'));if($r->filled('equipment_id'))$q->where('sl.equipment_id',$r->input('equipment_id'));if($r->filled('shift'))$q->where('sl.shift',$r->input('shift'));return response()->json(['success'=>true,'data'=>$q->orderByDesc('sl.logged_at')->limit(200)->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}
 public function store(Request $r){$equipmentId=$r->input('equipment_id');$status=$r->input('status');$stopReason=$r->input('stop_reason_id');$shift=$r->input('shift');$remarks=$r->input('remarks');if(!$equipmentId||!$status||!$shift)return response()->json(['success'=>false,'message'=>'equipment_id, status, and shift are required'],400);if(!in_array($status,['RUNNING','STOPPED'],true))return response()->json(['success'=>false,'message'=>'Invalid status'],400);if($status==='STOPPED'&&!$stopReason)return response()->json(['success'=>false,'message'=>'Stop reason is required when reporting STOPPED'],400);if(!in_array($shift,['A','B','C','G'],true))return response()->json(['success'=>false,'message'=>'Invalid shift'],400);
  try{$result=DB::transaction(function()use($r,$equipmentId,$status,$stopReason,$shift,$remarks){$eq=DB::table('equipment')->where('id',$equipmentId)->where('active',true)->lockForUpdate()->first();if(!$eq)return ['error'=>response()->json(['success'=>false,'message'=>'Equipment not found'],404)];if($eq->current_status===$status)return ['error'=>response()->json(['success'=>false,'message'=>"Equipment is already $status. Log a different status."],409)];if($status==='RUNNING'){$aj=DB::table('jobs')->select('job_number','title','status')->where('equipment_id',$equipmentId)->where('status','!=','CLOSED')->orderByDesc('created_at')->first();if($aj)return ['error'=>response()->json(['success'=>false,'message'=>"Cannot mark RUNNING — active job {$aj->job_number} ({$aj->status}) must be CLOSED first.",'active_job'=>(array)$aj],400)];}if($stopReason&&!DB::table('stop_reasons')->where('id',$stopReason)->where('active',true)->exists())return ['error'=>response()->json(['success'=>false,'message'=>'Invalid stop reason'],400)];$logId=DB::table('shift_logs')->insertGetId(['equipment_id'=>$equipmentId,'operator_id'=>$this->user($r)->id,'shift'=>$shift,'shift_date'=>now()->toDateString(),'status'=>$status,'stop_reason_id'=>$stopReason?:null,'remarks'=>$remarks?:null,'logged_at'=>now()]);$log=DB::table('shift_logs')->where('id',$logId)->first();DB::table('equipment')->where('id',$equipmentId)->update(['current_status'=>$status,'updated_at'=>now()]);$bd=null;if($status==='STOPPED'&&!DB::table('breakdowns')->where('equipment_id',$equipmentId)->where('status','OPEN')->exists()){$seq=DB::table('breakdowns')->whereDate('start_time',now()->toDateString())->count()+1;$bdNo='BD-'.now()->format('Ymd').'-'.str_pad((string)$seq,4,'0',STR_PAD_LEFT);$bdId=DB::table('breakdowns')->insertGetId(['bd_number'=>$bdNo,'equipment_id'=>$equipmentId,'shift_log_id'=>$logId,'initial_reason_id'=>$stopReason,'start_time'=>now(),'status'=>'OPEN','created_at'=>now(),'updated_at'=>now()]);$bd=DB::table('breakdowns')->where('id',$bdId)->first();}return ['log'=>$log,'bd'=>$bd];});if(isset($result['error']))return $result['error'];$this->audit->log($this->user($r)->id,'LOG_'.$status,'shift_logs',$result['log']->id,['equipment_id'=>$equipmentId,'status'=>$status,'stop_reason_id'=>$stopReason,'breakdown_id'=>$result['bd']->id??null],$r->ip());return response()->json(['success'=>true,'message'=>$status==='STOPPED'?('Equipment stopped. Breakdown '.($result['bd']->bd_number??'').' created.'):'Equipment marked as RUNNING.','data'=>['shift_log'=>LegacyResponse::normalize($result['log']),'breakdown'=>LegacyResponse::normalize($result['bd'])]],201);}catch(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}}
}
